"""Ask Hermes to investigate node generated by aotn_node_helper."""

from typing import Any, ClassVar, Dict, List, Optional

from ...node_base import Node, NodeContext
from ...node_category import NodeCategory


class HermesInvestigateNode(Node):
    """Queue one report-only investigation of the supplied evidence."""

    node_type: ClassVar[str] = 'hermes_investigate_node'
    display_name: ClassVar[str] = 'Ask Hermes to investigate'
    default_alias: ClassVar[str] = 'Ask Hermes to investigate'
    description: ClassVar[str] = 'Queue one report-only investigation of the supplied evidence'
    category: ClassVar[str] = NodeCategory.IO
    primary_family: ClassVar[str] = 'Outputs'
    tags: ClassVar[List[str]] = ['Hermes', 'investigation', 'incident']
    icon_name: ClassVar[str] = 'search'
    color_hint: ClassVar[str] = 'amber'
    group: ClassVar[Optional[str]] = 'Hermes'
    selector_section: ClassVar[Optional[str]] = None
    input_ports: ClassVar[List[str]] = ['input', 'evidence']
    output_ports: ClassVar[List[str]] = ['default']
    input_port_metadata: ClassVar[Dict[str, Dict[str, Any]]] = {'input': {'name': 'What happened', 'description': '', 'data_type': 'string', 'required': True, 'sources': ['upstream', 'vault', 'configured']}, 'evidence': {'name': 'Short excerpts', 'description': '', 'data_type': 'string', 'required': False, 'sources': ['upstream', 'vault', 'configured']}}
    output_port_metadata: ClassVar[Dict[str, Dict[str, Any]]] = {'default': {'name': 'Request id', 'description': 'The new request id, or the original id for a skipped repeat', 'data_type': 'string', 'required': True, 'to': ['downstream', 'vault'], 'pass_through': True}}
    default_config: ClassVar[Dict[str, Any]] = {'input_source': 'Configured', 'input_vault_key': '', 'input': '', 'evidence_source': 'Configured', 'evidence_vault_key': '', 'evidence': '', 'when': '', 'investigate': '', 'repeat_key': '', 'skip_repeats_minutes': 60, 'transient_output': True, 'dead_drop_passthrough': False, 'transient_outputs': [], 'vault_write': False, 'vault_write_key': '', 'vault_write_description': ''}
    config_schema: ClassVar[Dict[str, Dict[str, Any]]] = {'input_source': {'type': 'select', 'label': 'Input source', 'options': ['Upstream payload', 'Vault', 'Configured'], 'tab': 'Source', 'section': 'Required Inputs'}, 'input_vault_key': {'type': 'string', 'label': 'Input Vault key', 'required': False, 'tab': 'Source', 'section': 'Required Inputs', 'vault_type': 'string', 'visible_when': {'input_source': 'Vault'}}, 'input': {'type': 'multiline', 'label': 'What happened', 'height': 4, 'tab': 'Parameters', 'visible_when': {'input_source': 'Configured'}}, 'evidence_source': {'type': 'select', 'label': 'Evidence source', 'options': ['Upstream payload', 'Vault', 'Configured'], 'tab': 'Source', 'section': 'Optional Inputs'}, 'evidence_vault_key': {'type': 'string', 'label': 'Evidence Vault key', 'required': False, 'tab': 'Source', 'section': 'Optional Inputs', 'vault_type': 'string', 'visible_when': {'evidence_source': 'Vault'}}, 'evidence': {'type': 'multiline', 'label': 'Short excerpts (optional)', 'height': 4, 'description': 'Evidence gathered by the workflow. Hermes cannot read files.', 'tab': 'Parameters', 'visible_when': {'evidence_source': 'Configured'}}, 'when': {'type': 'string', 'label': 'When (optional)', 'placeholder': 'Blank: now', 'tab': 'Parameters'}, 'investigate': {'type': 'multiline', 'label': 'What to check', 'height': 4, 'description': 'Report only. No tools or changes. Daily limit is in Options.', 'tab': 'Parameters'}, 'repeat_key': {'type': 'string', 'label': 'Repeat key', 'placeholder': 'same run + node + branch', 'tab': 'Parameters'}, 'skip_repeats_minutes': {'type': 'number', 'label': 'Skip repeats for (minutes)', 'minimum': 0, 'maximum': 1440, 'tab': 'Parameters'}}
    ui_hints: ClassVar[Dict[str, Any]] = {}
    error_definitions: ClassVar[List[Dict[str, Any]]] = [{'code': 'input_missing', 'description': 'Enter what happened and what to check.', 'retryable': False}, {'code': 'invalid_time', 'description': 'Enter a timestamp with a time zone, or leave When blank.', 'retryable': False}, {'code': 'request_too_large', 'description': 'This investigation request is too long.', 'retryable': False}, {'code': 'daily_limit', 'description': 'The daily investigation limit has been reached.', 'retryable': False}, {'code': 'inbox_full', 'description': 'The investigation inbox is full.', 'retryable': False}, {'code': 'inbox_busy', 'description': 'The investigation inbox is busy. Try later.', 'retryable': False}, {'code': 'inbox_unwritable', 'description': 'The investigation request could not be saved.', 'retryable': False}, {'code': 'inbox_invalid', 'description': 'The investigation inbox needs checking.', 'retryable': False}]

    async def execute(self, context: NodeContext) -> None:
        from ... import hermes_investigations as inbox, hermes_folder
        from ...node_errors import NodeError
        try:
            inbox.validate_outputs(self.config)
            evidence = inbox.source(self.config, context, 'evidence')
            rid = inbox.enqueue(context,
                inbox.source(self.config, context, 'input'),
                '' if evidence is None else evidence,
                self.config.get('investigate', ''), self.config.get('when', ''),
                self.config.get('repeat_key', ''), self.config.get('skip_repeats_minutes', 60))
            hermes_folder.finish(self, context, rid, 'string')
        except NodeError as exc:
            context.signal_error(exc)
